"""Author bounded per-spell damage provenance decisions for Director conference."""
from datetime import datetime,timezone
import json
from apply_di7_ap_as_01 import G,R,A,info,encoded

def main():
 out=R/'data/director/spell_review/persistent_damage_20_root_proposal_04.json';report=A/'PERSISTENT_DAMAGE_20_ROOT_CHECK_04.json'
 assert not out.exists() and not report.exists()
 oldp=R/'data/director/spell_review/persistent_damage_20_source_convergence_01.json';old=json.loads(oldp.read_bytes())
 regp=R/'data/director/spell_review/accepted_interface_registry_03.json';reg=json.loads(regp.read_bytes())
 mappings=[]
 def row(sid,parts,reason):mappings.append({'spellId':sid,'status':'NEW source-specific proposal, requires Director agreement','components':parts,'reason':reason})
 def component(name,kind,checkpoint,carry):return {'name':name,'rootKind':kind,'dealer':'actual original caster character; no creature identity is created for a field, beam or object cannon','creationCheckpoint':checkpoint,'descendants':carry}
 direct=lambda name='initial packet':component(name,'new recipient-specific direct root','At actual admitted original recipient damage resolution, before defenses; shared dice do not merge recipients.','Pure transfer branches retain this root and its Null flag; no condition or attack identity is copied by transfer.')
 field=lambda name:component(name,'new recipient-specific exposure root','Each independently due, unsuppressed and exposure-cap-eligible field event, before damage RNG/consequences. Re-evaluate actual caster Veil at this root; denied or consumed-without-effect opportunities create no damaging root.','All terminal branches of this one exposure inherit its flag. Later independently due exposures are not descendants merely because the same field instance remains.')
 attachment=lambda name:component(name,'one recipient/application root','When this source actually establishes its target-attached damage component; snapshot dealer then, even if a later cap consumes the first scheduled opportunity without damage.','All expressly scheduled packets of that application retain its original flag. Suppression, immunity, healing, initiative transition and later caster Veil changes do not refresh it; a genuinely new admitted replacement application creates a new root.')
 row('inferno-wave',[direct(),component('finite ordinary ignited fuel','one ignition/patch provenance record; recipient-specific damage roots descend from it','At successful ignition of each admitted finite patch, store actual igniting caster and then-current Null flag. On that patch damaging a later recipient, allocate recipient-specific descendants from that stored provenance.','The same finite patch keeps its origin flag through its short printed life. This proposal grants no spreading fire, fuel, global ownership, or provenance for an independently ignited/spread hazard.')],'The immediate wave and physical ignition are distinct original outputs. Preserve causal origin without reclassifying mundane fire as a maintained spell. Physical propagation remains a separately unresolved environment decision.')
 for sid in ['freezing-rain','wall-of-fire','flame-typhoon','blood-fog','crystalline-growth']:
  row(sid,[field('each expressly scheduled/entry/contact damage opportunity')],'This is an explicit mapping analogous to, but not automatically inherited from, Forbiddance. Wall crossing and nearby categories remain distinct; source caps and clocks decide whether an actual exposure exists.')
 row('ice-storm',[direct('one mixed initial packet')],'Both types are one recipient damage event; magical residual difficult terrain creates no damage root.')
 row('vitriolic-sphere',[component('initial impact plus delayed acid rider','one original recipient root','At initial admitted impact, before immediate packet; retain save factor.','The single admitted future rider is a descendant of this root on either initial save branch under the pending spell proposal. Later spell applications create new roots.')],'Do not re-evaluate Null at the delayed marker or invent a root for empty recipient sets.')
 row('storm-sphere',[field('each area pulse'),component('operated lightning bolt','new attack root','On each actually authorized Bonus Action bolt attack; dealer remains caster although source-authorized spatial origin is sphere.','One bolt and its pure-transfer branches, with actual attack identity and critical procedure. A bolt is independent of its field pulse root.')],'No root comes from an unavailable BA, missed owner command or automatic replay.')
 row('immolation',[component('initial fire and admitted attached burning','one original recipient/application root','At initial admitted fire event; if failed-save burning component establishes, attach it to this original root.','All four possible target-END packets inherit the original flag; later source-family arbitration may consume a scheduled tick without damage. Recast is a new application, never a flag refresh on the old one.')],'Preserve original application provenance across recurring fire. Family/cure disposition remains independently pending.')
 row('arcane-mortar',[component('each actually fired shot','new caster-dealt attack root','At an actually executed authorized cannon shot; the cannon is an object, not a newly invented character/minion dealer.','Only that shot and its legitimate damage descendants. Repair or suppression cannot reset shot count or create another root.')],'Explicit local caster attribution is needed; an object cannon does not automatically inherit creature-dealer rules.')
 row('sonic-collapse',[direct('initial thunder packet'),component('the one source-authored collapse debris packet','descendant of the collapsed section initial root','When this cast actually causes the admitted weak section to collapse, retain that section damage-root caster/Null flag. Allocate separate recipient descendants for its bounded one-time debris exposure.','Retain material mass and source limits. A later independent structural collapse or ordinary creature fall does not inherit this spell root without its own source rule.')],'The proposed weak-structure rider causes a specific immediate hazard. Do not make the caster own all future rubble, or conflate debris with ordinary Falling.')
 row('leeching-plague',[attachment('four drain installments')],'Initial failed save establishes a periodic component, not immediate damage. Healing uses eligible terminal branches of each actual tick once; root identity never substitutes for source-specific donor restrictions.')
 row('mass-decay',[component('initial damage and admitted decay rider','one original recipient/application root','At initial admitted recipient damage; failed save admits the three-START descendant schedule.','Keep original flag for each later ordinal, even if the shared cast ordinal RNG is first generated by a different recipient. Each recipient root is distinct despite the shared ordinal faces.')],'Shared roll timing cannot rewrite dealer state or target-specific ancestry.')
 row('enervation',[component('initial and each separately maintained pulse attack','new root per real Action attack','At each genuinely new authorized initial/maintenance attack; sample dealer state then.','That pulse and its eligible terminal damage/healing accounting only. Future paid Action attacks are new activations under the maintained channel.')],'A retained concentration tether is not itself a reroll or a reason to reuse an earlier attack root. No root for skipped maintenance or extra-turn attempts.')
 row('rift-spiral',[direct()],'Half-Speed/Prone is a separately admitted condition on the original failed-save target; damage transfer never copies it.')
 row('synaptic-static',[direct()],'Repeated penalty d6 operations are modifiers, not damage packets; they create no damage root. Original modifier snapshots and Fate eligibility await exact DE4 disposition.')
 row('greater-phantasmal-killer',[attachment('independent recurring nightmare damage')],'Propose the same explicit establishment checkpoint as lower Phantasmal Killer while retaining this source’s different 4d6 amount, no implied fear, access and schedule. Lower DE4 is still pending; this is separate scoped authorship.')
 for sid in ['aura-of-dread','shadow-of-moil']:row(sid,[],'This procedure creates no damage event. A numeric penalty or resistance record has no damage root; unrelated incoming damage keeps its own actual source.')
 ids={s['id'] for s in old['spells']};assert {x['spellId'] for x in mappings}==ids and len(mappings)==20
 vectors=[{'id':'P20-ROOT-01','scope':'Composition of proposed attachment mapping with accepted Null provenance; no setup cast claimed','input':'Leeching damage component establishes while actual caster Null flag is true. Caster later successfully purges Veil before two due ticks.','expected':'Both ticks use true; no newly allocated application or flag mutation. An actually admitted recast after purge creates a separate false root.'},
 {'id':'P20-ROOT-02','scope':'Composition of proposed field mapping','input':'A Storm area pulse occurs with caster Veil true. Veil later ends; next genuinely due field pulse and separately authorized bolt occur.','expected':'First pulse root true; later pulse root false and bolt root false. Retain separate recipient roots, source caps and owner BA spending.'},
 {'id':'P20-ROOT-03','scope':'Composition of proposed Mass Decay mapping','input':'Recipients A and B were both admitted while caster Veil true; A first generates ordinal2 faces after caster purge, B reaches its own ordinal2 later.','expected':'Both original recipient roots remain true; common faces are reused under the pending ordinal rule, but their schedules, HP, defenses and terminal branches stay distinct.'},
 {'id':'P20-ROOT-04','scope':'Composition of explicit source-origin exceptions requiring review','input':'Inferno finite patch ignited while caster Veil true; caster purges before an actual later eligible exposure. Separately Sonic section collapse has a false root.','expected':'That patch’s inherited damage is true; Sonic’s one explicitly caused debris event retains false. No claim about independently spreading fire, later unrelated collapse, or creature Falling.'}]
 bindings=[info(oldp),info(regp)]
 for i in [9,10,50]:
  b=reg['entries'][i]['currentAuthoritativeSource'];p=G/b['path'];assert info(p)=={k:b[k] for k in ['path','bytes','sha256']}
  if info(p) not in bindings:bindings.append(info(p))
 de4=R/'data/director/spell_proposals/divination_enchantment_rank4_current_05.json';bindings.append(info(de4))
 assert sum(bool(x['components']) for x in mappings)==18
 out.write_bytes(encoded({'id':'PERSISTENT-DAMAGE-20-ROOT-PROPOSAL-04','recordedAtUtc':datetime.now(timezone.utc).isoformat(),'status':'Unsent NEW per-source authorship; no accepted interface modified','mapping':mappings,'vectors':vectors,'decisionsForDirector':['Agree or correct per-source creation checkpoints, especially ongoing target applications versus new field exposures.','Agree or correct physical finite ignition attribution and one immediate Sonic debris descendant; these must not become a universal environment law.','Agree or correct object mortar caster attribution and separate real Action Enervation roots.','Resolve against actual accepted DE4 result before binding Greater Phantasmal Killer; do not assume lower spell acceptance.'],'integrationBoundary':'No root allocation itself deals damage, claims exposure, creates resources, triggers Wounds or death, or supplies eligibility. Accepted Null recipient lifecycles and pure-transfer restrictions remain unchanged. Suppressed/lost opportunities never bank damage. Shared RNG is not root identity. Source record creation does not expose hidden events to players.','sourceBindings':bindings,'acceptedCountsUnchanged':{'reviewed':465,'pending':383},'newRuleAdoptions':0,'runtimeTestsExecuted':0,'sourceInformationDeleted':0}))
 report.write_bytes(encoded({'artifact':info(out),'checkCount':7,'failureCount':0,'checks':['20 exact pending identities covered once','18 damage sources and2 nondamaging sources distinguished','Actual registry9 authority binding verified','Actual registry10 authority binding verified','Actual registry50 authority binding verified','DE4 dependency remains pending','4 explicitly composition-only vectors retained'],'scope':'Structural coverage and actual dependency bindings only, not semantic approval or game runtime.'}))
 print(json.dumps({'artifact':info(out),'checks':7,'failures':0}))

if __name__=='__main__':main()
